  try{cache.put('zl_arm','1',0);}catch(e){}
  var DL='(function(){try{var a=String(cache.get("zl_arm")||"");if(a==="1"){cache.put("zl_arm","2",0);return String(result);}var o={};try{o=JSON.parse(String(cache.get("zl_ctok2")||"")||"{}")||{};}catch(e){o={};}var t=String(o.t||"");if(t){var base=String((function(){var b="";try{b=String(cache.get("zl_base")||"");}catch(e){}return b||String(source.bookSourceUrl||"");})());var q=base.indexOf("#");if(q>=0){base=base.substring(0,q);}while(base.length>0&&base.charAt(base.length-1)==="/"){base=base.substring(0,base.length-1);}var ex=String(cookie.getCookie(base)||"");if(ex.indexOf("c_token=")>=0){ex=ex.replace(/; *c_token=[^;]*/,"").replace(/; *c_time=[^;]*/,"");}var v=ex?(ex+"; c_token="+t+"; c_time=0.4"):("c_token="+t+"; c_time=0.4");try{cookie.setCookie(base,v);}catch(e){}}return String(result);}catch(e){return String(result);}})()';
  var o={type:ext,js:DL};
  return page+','+JSON.stringify(o);
 }catch(e){return '';}
