      var _log=[];
      try{_log=JSON.parse(String(cache.get('zl_log')||'')||'[]')||[];}catch(e){_log=[];}
      if(!_log||_log.length==null){_log=[];}
      _log.push(_dbg);
      while(_log.length>5){_log.shift();}
      cache.put('zl_log',JSON.stringify(_log),0);
