    if(j.filesizeString){_fmt.push(String(j.filesizeString));}
    if(j.pages){_fmt.push(String(j.pages)+' 页');}
    if(_fmt.length){info.push('📄 格式：'+_fmt.join(' · '));}
    var _sc=[];
    if(j.qualityScore!=null){_sc.push('⭐ '+String(j.qualityScore)+' / 5');}
    if(j.interestScore!=null){_sc.push('🔥 热度 '+String(j.interestScore));}
    if(_sc.length){info.push(_sc.join('　'));}
